#include "dynamic_session_random.hpp"
#include "resident/model/common_rng.hpp"
#include "resident/domains/travel/movement_exact_detail.hpp"
#include <charconv>
#include <limits>
namespace hanmo::resident {using namespace movement_detail;
namespace {
constexpr const char* original_algorithm="godot:4.7.2-stable (official)";
std::uint64_t canonical_u64(const StableId& text){std::uint64_t value=0;auto parsed=std::from_chars(text.data(),text.data()+text.size(),value);if(parsed.ec!=std::errc()||parsed.ptr!=text.data()+text.size()||std::to_string(value)!=text)fail("InvalidDynamicMilitaryUnsignedState",text);return value;}
bool same_stream(const DynamicMilitaryStreamIdentity& a,const DynamicMilitaryStreamIdentity& c){return a.session_ref==c.session_ref&&a.generation==c.generation&&same_source(a.initialization_source_ref,c.initialization_source_ref);}
void valid_stream(const DynamicMilitaryStreamIdentity& s){if(s.session_ref.empty()||s.generation<=0||!source_valid(s.initialization_source_ref))fail("DynamicMilitaryRandomInitializationRequired",s.session_ref);}
}
Status validate_dynamic_military_random_state(const DynamicMilitarySessionRandom& s){return status([&]{valid_stream(s.stream_identity);if(s.algorithm_version!=original_algorithm||!source_valid(s.last_commit_source_ref))fail("DynamicMilitaryRandomBackendMismatch",s.stream_identity.session_ref);canonical_u64(s.seed);canonical_u64(s.current_state);});}
Status validate_dynamic_military_random_slot(const DynamicMilitaryRandomSlot& s){return status([&]{valid_stream(s.stream_identity);if(!source_valid(s.effect_ref)||s.algorithm_version!=original_algorithm||s.stage<DynamicMilitaryRandomStage::strike||s.stage>DynamicMilitaryRandomStage::original_ai_decision||s.requested_min>s.requested_max||s.before_draw_ordinal==std::numeric_limits<std::uint64_t>::max()||s.after_draw_ordinal!=s.before_draw_ordinal+1)fail("DynamicMilitaryRandomSlotMismatch",s.effect_ref.id);canonical_u64(s.seed);const auto before=canonical_u64(s.before_state),after=canonical_u64(s.after_state);const auto original=take(godot_pcg32_range(rng_detail::signed_bits(before),s.requested_min,s.requested_max));if(original.value!=s.draw_result||rng_detail::unsigned_bits(original.next_state)!=after)fail("DynamicMilitaryRandomOriginalDrawMismatch",s.effect_ref.id);});}
Outcome<DynamicMilitaryRandomSlot> draw_dynamic_military_random_in_candidate(DynamicMilitarySessionRandom& current,const SourceRef& effect,DynamicMilitaryRandomStage stage,Integer low,Integer high){return guard<DynamicMilitaryRandomSlot>([&]{take(validate_dynamic_military_random_state(current));if(!source_valid(effect)||low>high||stage<DynamicMilitaryRandomStage::strike||stage>DynamicMilitaryRandomStage::original_ai_decision)fail("DynamicMilitaryRandomEffectRequired",effect.id);if(current.draw_ordinal==std::numeric_limits<std::uint64_t>::max())fail("DynamicMilitaryRandomOrdinalOverflow",effect.id);const auto draw=take(godot_pcg32_range(rng_detail::signed_bits(canonical_u64(current.current_state)),low,high));DynamicMilitaryRandomSlot out{effect,stage,current.stream_identity,current.algorithm_version,low,high,current.seed,current.current_state,std::to_string(rng_detail::unsigned_bits(draw.next_state)),current.draw_ordinal,current.draw_ordinal+1,draw.value};take(validate_dynamic_military_random_slot(out));current.current_state=out.after_state;current.draw_ordinal=out.after_draw_ordinal;current.last_commit_source_ref=effect;return out;});}
Status validate_dynamic_military_random_chain(const DynamicMilitarySessionRandom& before,const std::vector<DynamicMilitaryRandomSlot>& slots,const DynamicMilitarySessionRandom& after){return status([&]{take(validate_dynamic_military_random_state(before));take(validate_dynamic_military_random_state(after));if(!same_stream(before.stream_identity,after.stream_identity)||before.algorithm_version!=after.algorithm_version||before.seed!=after.seed)fail("DynamicMilitaryRandomStreamChanged",before.stream_identity.session_ref);const StableId* state=&before.current_state;std::uint64_t ordinal=before.draw_ordinal;const SourceRef* last=&before.last_commit_source_ref;for(const auto& slot:slots){take(validate_dynamic_military_random_slot(slot));if(!same_stream(before.stream_identity,slot.stream_identity)||slot.seed!=before.seed||slot.algorithm_version!=before.algorithm_version||slot.before_state!=*state||slot.before_draw_ordinal!=ordinal)fail("DynamicMilitaryRandomChainMismatch",slot.effect_ref.id);state=&slot.after_state;ordinal=slot.after_draw_ordinal;last=&slot.effect_ref;}if(after.current_state!=*state||after.draw_ordinal!=ordinal||!same_source(after.last_commit_source_ref,*last))fail("DynamicMilitaryRandomFinalStateMismatch",before.stream_identity.session_ref);});}
bool same_dynamic_military_random_slot(const DynamicMilitaryRandomSlot& a,const DynamicMilitaryRandomSlot& z){
 return same_source(a.effect_ref,z.effect_ref)&&a.stage==z.stage&&same_stream(a.stream_identity,z.stream_identity)&&
  a.algorithm_version==z.algorithm_version&&a.requested_min==z.requested_min&&a.requested_max==z.requested_max&&
  a.seed==z.seed&&a.before_state==z.before_state&&a.after_state==z.after_state&&
  a.before_draw_ordinal==z.before_draw_ordinal&&a.after_draw_ordinal==z.after_draw_ordinal&&a.draw_result==z.draw_result;
}

}
